function isIndexMembrane(id) {
  return /(^|_)0001_INDEX$/i.test(id) || /^0001_INDEX$/i.test(id);
}
function cleanTail(tail) {
  return (tail || '').replace(/[}\]]\s*$/g, '').replace(/^\s+/, ' ').trimEnd();
}

