  if (folded) { try { editor.selection = new vscode.Selection(pair.start, 0, pair.start, 0); } catch (_) {} }
  await vscode.commands.executeCommand(folded ? 'editor.fold' : 'editor.unfold', { selectionLines: [pair.start] });
