const HTOC_MARKER_RE = /(?:<!--|\/\*)\s*mHTOC1\s+([0-9a-fA-F]*)\s*(?:-->|\*\/)/;
const _htocSourceCache = new WeakMap(); // document -> { version, markerLine, data }
