    let best=null,bd=Infinity;
    rows.forEach(function(r){const rc=r.getBoundingClientRect();const c=rc.top+rc.height/2;const d=Math.abs(c-at.y);if(d<bd){bd=d;best=r;}});
    rows.forEach(function(r){r.classList.remove('toc-child-center');});
