/* v0.9.711: 全tip共通。tipの右端をカーソルの約6文字左に置く間隔(px)。俊克 am09:53「ポインターより6文字くらい離す・見えないとストレス」。 */
const TIP_GAP_PX=44;
function showTocTip(ev){if(!tocTooltip)return;if(window.__tocChildOpen)return;/* v0.9.999123: 副メニュー表示中はtip抑止 */if(window.__headWrapUntil&&Date.now()<window.__headWrapUntil){hideTocTip();return;}if(window.__refDeciding){hideTocTip();return;}/* v0.9.99988: セグメント決定中はtip抑制(俊克) *//* v0.9.805: H-TOC項目のコメント編集中(toc-valueにフォーカス)はtip非表示=編集の邪魔をしない。 */{const ae=document.activeElement;if(ae&&ae.classList&&ae.classList.contains('toc-value')){hideTocTip();return;}}const el=(ev.target&&ev.target.closest)?ev.target.closest('[data-tip],[title]'):null;/* v0.9.712: native title を data-tip に遅延移行(ネイティブtipを抑止し共通の左伸ばしtipに一本化)。JSが.titleを再設定しても次のhoverで反映。 */if(el&&el.hasAttribute('title')){const tt=el.getAttribute('title');if(tt)el.setAttribute('data-tip',tt);el.removeAttribute('title');}const t=el?el.getAttribute('data-tip'):'';if(!t){hideTocTip();return;}/* v0.9.691: split the " | " separated parts (Created/Checked/Cite) onto separate lines for readability (俊克 am11:38). 改行は String.fromCharCode(10) で安全に(テンプレートリテラル回避)。CSSは white-space:pre-line。 */tocTooltip.textContent=String(t).split(' | ').join(String.fromCharCode(10));/* v0.9.686: grow the tip LEFT from the cursor (Me Dock sits at the screen's right edge, so a right-growing tip clips); wrap to 2+ lines. Anchor the tip's RIGHT edge ~12px left of the cursor. */tocTooltip.style.display='block';/* v0.9.99981(改良1 俊克): 開いているプルダウン(.bm-pop.on)内の項目tipは、マウスX追従をやめて ポップアップ左端に接した固定位置に出す(メニューを隠さない)。縦は項目に合わせる。 */{const _popEl=el.closest&&el.closest('.bm-pop');if(_popEl&&_popEl.classList.contains('on')){const pr=_popEl.getBoundingClientRect();const tw=tocTooltip.offsetWidth||160,h=tocTooltip.offsetHeight||20;const leftEdge=pr.left-1-tw;if(leftEdge>=4){/* 左に余地あり: ポップアップ左端の左に接し上端揃え */tocTooltip.style.left='auto';tocTooltip.style.right=(window.innerWidth-pr.left+1)+'px';let top=pr.top;if(top+h>window.innerHeight-2)top=window.innerHeight-h-2;if(top<2)top=2;tocTooltip.style.top=top+'px';}else{/* v0.9.99985(改良1 俊克): 左に余地なし(孫メニュー等)→ポップアップ上端の上に接して表示(tip下端=ポップアップ上端) */tocTooltip.style.right='auto';let left=pr.left;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=pr.top-h-1;if(top<2)top=pr.bottom+1;tocTooltip.style.top=top+'px';}return;}}/* v0.9.769: タブのtipは常に"上空"に出す(ドラッグ中にドロップ位置を隠さないため)。タブ左に揃え、上に余地が無ければ下。 */const _tabEl=el.closest&&el.closest('.toc-tab');if(_tabEl){const r=_tabEl.getBoundingClientRect();const tw=tocTooltip.offsetWidth||120,h=tocTooltip.offsetHeight||20;tocTooltip.style.right='auto';let left=r.left;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=r.top-h-6;if(top<2)top=r.bottom+6;tocTooltip.style.top=top+'px';return;}/* v0.9.829: Mepyの挨拶tipは必ず顔の外に(俊克 am03:43)。顔(membrane-visual)の上に中央寄せ・上に余地が無ければ下。 *//* v0.9.881: Format色ピッカー(スウォッチ/スロット)のtipは要素の真上に近接表示(離れすぎ対策・俊克 6/15 pm00:24)。 */const _fmtEl=el.closest&&el.closest('#fmt-pop');if(_fmtEl){const r=el.getBoundingClientRect();const tw=tocTooltip.offsetWidth||80,h=tocTooltip.offsetHeight||18;tocTooltip.style.right='auto';let left=r.left+(r.width-tw)/2;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=r.top-h-5;if(top<2)top=r.bottom+5;tocTooltip.style.top=top+'px';return;}const _mepyEl=el.closest&&el.closest('.mepy-hello');if(_mepyEl){const face=document.getElementById('membrane-visual');const fr=(face||_mepyEl).getBoundingClientRect();const tw=tocTooltip.offsetWidth||120,h=tocTooltip.offsetHeight||20;tocTooltip.style.right='auto';let left=fr.left+(fr.width-tw)/2;if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=fr.top-h-8;if(top<2)top=fr.bottom+8;tocTooltip.style.top=top+'px';return;}const rowEl=(el.closest&&el.closest('.fixed-toc-item,.toc-pin'))||el;const rect=(rowEl&&rowEl.getBoundingClientRect)?rowEl.getBoundingClientRect():null;const tw=tocTooltip.offsetWidth||120;const h=tocTooltip.offsetHeight||20;if(ev.clientX-TIP_GAP_PX-tw<4){/* v0.9.713: 左伸ばしだと左端で見切れる(左端の細いボタン)→上に逃がして右方向に伸ばす(俊克 am10:48)。 */tocTooltip.style.right='auto';let left=(rect?rect.left:ev.clientX);if(left+tw>window.innerWidth-2)left=window.innerWidth-tw-2;if(left<2)left=2;tocTooltip.style.left=left+'px';let top=(rect?rect.top:ev.clientY)-h-4;if(top<2)top=(rect?rect.bottom:ev.clientY)+4;if(top+h>window.innerHeight-2)top=window.innerHeight-h-2;tocTooltip.style.top=top+'px';}else{/* 通常: カーソル6文字左から左伸ばし・行の上端に合わせる(プルダウン風)。 */tocTooltip.style.left='auto';tocTooltip.style.right=(window.innerWidth-ev.clientX+TIP_GAP_PX)+'px';let top=(rect?rect.top:ev.clientY)+1;if(top<2)top=2;if(top+h>window.innerHeight-2)top=window.innerHeight-h-2;tocTooltip.style.top=top+'px';}}
function hideTocTip(){if(tocTooltip)tocTooltip.style.display='none';}
/* v0.9.712: 全tip統一。webview全体で mousemove を拾い、data-tip / native title を持つ最近接要素に
   共通の左伸ばしtipを出す(showTocTip内で title→data-tip 遅延移行)。個別リスナ(fixedTocBody/format-tools)は廃止し1本化。 */
document.addEventListener('mousemove',showTocTip);
document.addEventListener('mouseleave',hideTocTip);
